function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.045);if(!isFighting){updateWorld(dt);}else updateFightScene(dt);renderer.render(scene,camera);}
function updateWorld(dt){const forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)+mobileVector.z;const side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+mobileVector.x;const len=Math.hypot(forward,side);if(len>.05){const sprint=keys.ShiftLeft||keys.ShiftRight;const speed=(sprint?7.2:4.2)*dt;const sin=Math.sin(cameraAngle),cos=Math.cos(cameraAngle);player.position.x+=(side*cos+forward*sin)/len*speed;player.position.z+=(-side*sin+forward*cos)/len*speed;player.position.x=clamp(player.position.x,-75,75);player.position.z=clamp(player.position.z,-72,72);player.rotation.y=Math.atan2(side*cos+forward*sin,-side*sin+forward*cos);if(sprint&&state.energy>0)state.energy=Math.max(0,state.energy-dt*.75);else state.energy=Math.min(100,state.energy+dt*.3);}
worldGroup.children.forEach(o=>{if(o.userData.npc){o.userData.walk+=dt;o.position.x+=Math.sin(o.userData.walk)*dt*.12;o.position.z+=Math.cos(o.userData.walk*.8)*dt*.1;o.rotation.y=o.userData.walk;}if(o.userData.rolling){o.position.z+=dt*1.1;if(o.position.z>78)o.position.z=-78;}});
