const target=new THREE.Vector3(player.position.x+Math.sin(cameraAngle)*cameraDistance,player.position.y+3.1,player.position.z-Math.cos(cameraAngle)*cameraDistance);camera.position.lerp(target,1-Math.pow(.002,dt));camera.lookAt(player.position.x,1.2,player.position.z);
}
function updateFightScene(dt){if(!player||!enemy)return;player.rotation.y=Math.atan2(enemy.position.x-player.position.x,enemy.position.z-player.position.z);enemy.rotation.y=Math.atan2(player.position.x-enemy.position.x,player.position.z-enemy.position.z);const sep=player.position.distanceTo(enemy.position);if(sep>2.6){enemy.position.lerp(new THREE.Vector3(player.position.x+(enemy.position.x-player.position.x)/sep*1.55,0,player.position.z+(enemy.position.z-player.position.z)/sep*1.55),dt*.23);}const camTarget=new THREE.Vector3(player.position.x+4,6,player.position.z+9);camera.position.lerp(camTarget,dt*1.8);camera.lookAt(0,1.2,0);if(fightTimer<=0){finishFight('decision');}}

