if(type==='training'){const classes=[['Heavy bag','Boxing','Power and combinations','Heavy bag rounds',5,9],['Focus mitts','Speed','Sharp hands and timing','Coach-led mitt work',6,10],['Wrestling drills','Wrestling','Entries, sprawls and control','Takedown practice',5,11],['BJJ rolling','BJJ','Position, transitions, submissions','Ground grappling',7,12],['Muay Thai pads','Muay Thai','Kicks, knees and clinch strikes','Thai pad rounds',6,10],['Strength circuit','Strength','Compound lifts and power','Weights & conditioning',5,9],['Road work','Cardio','Build your engine outdoors','Steady run',3,8],['Technical sparring','Grappling','Live MMA rounds sharpen everything','Controlled sparring',12,16]];html+=`<p class="modal-subtitle">Every session costs energy. Rest at home or eat well to recover. Membership is $80/month; individual sessions include gym access.</p><div class="modal-grid">${classes.map(([name,skill,desc,activity,cost,gain])=>`<div class="training-card"><div class="training-head"><b>${name}</b><span>+${gain} ${skill}</span></div><p>${desc}</p><button data-train="${skill}" data-cost="${cost}" data-gain="${gain}">${activity.toUpperCase()} · ${cost} ENERGY</button></div>`).join('')}</div>`;}
else if(type==='career'){const fights=state.record.slice(-6).reverse();html+=`<p class="modal-subtitle">An unknown amateur with a $500 bankroll. Win bouts, earn your pro license, climb the rankings and earn a shot at the world title.</p><div class="career-statbar"><div class="career-stat"><strong>${state.wins}-${state.losses}-${state.draws}</strong><small>RECORD</small></div><div class="career-stat"><strong>${state.ko}</strong><small>KNOCKOUTS</small></div><div class="career-stat"><strong>${state.subs}</strong><small>SUBMISSIONS</small></div><div class="career-stat"><strong>${state.rank?`#${state.rank}`:'—'}</strong><small>RANKING</small></div></div><button class="primary-button full" id="career-fight"><span>ACCEPT NEXT BOUT · $${350+state.wins*480} WIN BONUS</span><b>↗</b></button><h3 class="eyebrow" style="margin:20px 0 5px">FIGHT HISTORY</h3>${fights.length?fights.map(f=>`<div class="history-row"><b style="color:${f.result==='WIN'?'#9de0ba':'#e78062'}">${f.result}</b><span>${f.opponent} · ${f.method}</span><span>${f.date}</span></div>`).join(''):'<div class="history-row"><span>No bouts on the record. Your story starts tonight.</span></div>'}`;}
else if(type==='food'){html+=`<p class="modal-subtitle">Fuel the grind. A meal costs money but gets your energy back.</p><div class="modal-grid">${[['Recovery bowl','Protein, rice, greens · +25 energy',18],['Fighter’s special','Steak, eggs, potatoes · +50 energy',38],['Hydration pack','Electrolytes · +15 energy',9],['Sleep it off','Head home and recover · free',0]].map(([a,b,c])=>option(a,b,c,'🍽','food')).join('')}</div>`;}
else if(type==='shop'){html+=`<p class="modal-subtitle">Invest in training gear. Equipment improves the quality of your sessions.</p><div class="modal-grid">${[['Hand wraps','Protect your hands · +2 Boxing',35],['Training gloves','Bag work bonus · +2 Strength',85],['Road shoes','Better conditioning · +2 Cardio',70],['Foundry membership','Monthly membership · skip $80 gym fee',120]].map(([a,b,c])=>option(a,b,c,'◈','gear')).join('')}</div>`;}
else if(type==='property'){const homes=[['Room in a shared apartment','Basic bed. Your own corner of the city.',2200,3500],['Studio apartment','A quiet place to recover.',14500,17000],['Starter home','A small house with a little yard.',78000,87000],['Modern hillside house','Room to breathe. Room to grow.',365000,390000],['Champion’s mansion','The view from the top.',2450000,2600000]];html+=`<p class="modal-subtitle">Buy a place to sleep, recover and build equity. Daily rent is currently ${state.home?'$'+Math.round(state.home.price*.0015):'$550'}/month. A home is yours to keep.</p><div class="modal-grid">${homes.map(([a,b,c,v])=>option(a,b,c,'⌂','home',v)).join('')}</div>${state.home?`<button class="primary-button full" id="sleep-button" style="margin-top:10px"><span>SLEEP AT HOME · RESTORE ENERGY & HEALTH</span><b>☾</b></button>`:''}`;}
else if(type==='vehicle'){const cars=[['Pre-owned hatchback','Used wheels. Beats the bus.',2800,3200],['City motorcycle','Fast, cheap and nimble.',7600,8200],['Family SUV','Reliable all-weather ride.',32000,35000],['Track-ready coupe','A little taste of speed.',86500,94000],['Executive grand tourer','Arrive like a contender.',245000,265000]];html+=`<p class="modal-subtitle">A vehicle is an asset, not a cheat code. Ownership adds monthly upkeep, but puts the whole city within reach.</p><div class="modal-grid">${cars.map(([a,b,c,v])=>option(a,b,c,'▰','car',v)).join('')}</div>${state.ownedVehicles.length?`<div class="history-row" style="margin-top:10px"><span>GARAGE · ${state.ownedVehicles.map(v=>v.name).join(' · ')}</span><span>${state.activeVehicle?'OWNED':'ON FOOT'}</span></div>`:''}`;}
openModal(html);if(type==='training'){document.querySelectorAll('[data-train]').forEach(b=>b.onclick=()=>train(b.dataset.train,+b.dataset.cost,+b.dataset.gain));}document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buyItem(b.dataset.buy,b.dataset.name,+b.dataset.cost,+b.dataset.value));document.querySelectorAll('[data-food]').forEach(b=>b.onclick=()=>eat(b.dataset.name,+b.dataset.cost));if($('#career-fight'))$('#career-fight').onclick=()=>{closeModal();startFight();};if($('#sleep-button'))$('#sleep-button').onclick=sleepAtHome;
}
function option(name,desc,cost,icon,type,value=0){return `<button class="option-card" data-buy="${type}" data-name="${name}" data-cost="${cost}" data-value="${value}"><span class="option-icon">${icon}</span><span><b>${name}</b><small>${desc}</small><em>${cost===0?'FREE':'$'+cost.toLocaleString()}</em></span></button>`;}
function buyItem(type,name,cost,value){if(type==='home'&&state.home){toast('YOU ALREADY OWN A HOME');return;}const exists=type==='gear'&&state.gear.includes(name)||type==='car'&&state.ownedVehicles.some(v=>v.name===name);if(exists){toast('ALREADY OWNED');return;}if(state.cash<cost){toast(`NOT ENOUGH CASH · NEED $${(cost-state.cash).toLocaleString()}`);return;}state.cash-=cost;if(type==='home'){state.home={name,price:cost,value};state.ownedProperties.push(name);toast(`${name.toUpperCase()} PURCHASED · HOME SWEET HOME`);}else if(type==='car'){state.ownedVehicles.push({name,value});state.activeVehicle=name;toast(`${name.toUpperCase()} ADDED TO YOUR GARAGE`);}else{state.gear.push(name);const idx=name.includes('wraps')?0:name.includes('gloves')?6:8;if(name!=='Foundry membership')state.skills[idx]=Math.min(100,state.skills[idx]+2);toast(`${name.toUpperCase()} PURCHASED`);}save();openPanel(type==='home'?'property':type==='car'?'vehicle':'shop');}
function eat(name,cost){if(state.cash<cost){toast('NOT ENOUGH CASH');return;}state.cash-=cost;state.energy=Math.min(100,state.energy+(name.includes('special')?50:name.includes('bowl')?25:15));state.fatigue=Math.max(0,state.fatigue-5);timeAdvance(30);toast(`${name} · ENERGY RESTORED`);save();openPanel('food');}
function train(skill,cost,gain){if(state.energy<cost||state.health<25){toast(state.health<25?'YOU NEED MEDICAL RECOVERY':'TOO TIRED · REST OR GET A MEAL');return;}const i=skillNames.indexOf(skill);state.energy=Math.max(0,state.energy-cost);state.fatigue=Math.min(100,state.fatigue+cost*.75);state.skills[i]=Math.min(100,state.skills[i]+(state.gear.length?gain+1:gain));state.trainingCount++;state.health=Math.max(40,state.health-1);timeAdvance(70);addXP(18+gain);toast(`${skill.toUpperCase()} +${gain} · SESSION COMPLETE`);openPanel('training');}
function sleepAtHome(){if(!state.home){toast('YOU NEED A HOME');return;}state.energy=100;state.fatigue=Math.max(0,state.fatigue-70);state.health=100;timeAdvance(480);toast(`RESTED AT ${state.home.name.toUpperCase()} · FULL RECOVERY`);closeModal();}
function toggleMap(show){mapOpen=show;$('#map-overlay').classList.toggle('open',show);if(show){const art=$('#map-art');art.innerHTML=locationData.map(l=>`<div class="map-pin" style="left:${50+l.x/1.6}%;top:${50+l.z/1.3}%">◆ ${l.name}</div>`).join('')+`<div class="map-pin player" style="left:${50+player.position.x/1.6}%;top:${50+player.position.z/1.3}%">●</div>`;}}
document.addEventListener('click',e=>{if(e.target.closest('[data-mobile="interact"]'))interact();if(e.target.closest('[data-mobile="sprint"]')){keys.ShiftLeft=true;setTimeout(()=>keys.ShiftLeft=false,500);}});

