document.addEventListener('click',e=>{if(e.target.closest('[data-mobile="interact"]'))interact();if(e.target.closest('[data-mobile="sprint"]')){keys.ShiftLeft=true;setTimeout(()=>keys.ShiftLeft=false,500);}});

// Fight night: real-time cage bout, with readable arcade timing and RPG stat influence.
function startFight(){if(isFighting)return;if(state.health<30){toast('YOU’RE TOO HURT TO COMPETE · RECOVER FIRST');return;}closeModal();isFighting=true;fightLocked=false;fightTimer=180;round=1;fightIndex++;playerHP=state.health;playerStamina=Math.max(35,state.energy);enemyHP=100;enemyStamina=100;blockHeld=false;dodgeReady=false;worldGroup.visible=false;arenaGroup.visible=true;$('#fight-hud').classList.add('active');$('#fight-log').textContent='The referee calls you to the center of the cage.';$('#round-pill').textContent='ROUND 1 / 3';const names=['MILO “THE WALL” VEGA','DEVON “QUICK HANDS” PRICE','LUIS “EL TORO” SANTOS','MARCUS “NIGHT SHIFT” COLE','KENJI “THE CLINIC” MORI'];$('#enemy-name').textContent=names[(state.wins+state.losses)%names.length];if(enemy)arenaGroup.remove(enemy);enemy=makePerson(0x456479,0x353934);enemy.position.set(1.7,0,-.7);arenaGroup.add(enemy);player.visible=true;player.position.set(-1.7,0,.7);arenaGroup.add(player);player.rotation.y=0;updateUI();camera.position.set(4,6,9);camera.lookAt(0,1.2,0);$('#fight-button').textContent='FIGHT IN PROGRESS';fightInterval=setInterval(()=>{if(!isFighting)return;fightTimer--;if(fightTimer===120||fightTimer===60){round++;$('#round-pill').textContent=`ROUND ${round} / 3`;$('#fight-log').textContent=`Round ${round}. Back to the center.`;playerStamina=Math.min(100,playerStamina+12);enemyStamina=Math.min(100,enemyStamina+10);}$('#fight-timer').textContent=`0${Math.floor(fightTimer/60)}:${String(fightTimer%60).padStart(2,'0')}`;if(Math.random()<.18)enemyAttack();if(fightTimer<=0){const result=playerHP>enemyHP?'decision':'decision';finishFight(result);}},1000);document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>fightMove(b.dataset.move));toast('BOUT STARTED · MAKE YOUR MOVE');}
function fightMove(move){if(!isFighting||fightLocked)return;const cost={jab:5,kick:13,grapple:16,block:0,dodge:8,submit:18}[move]||5;if(playerStamina<cost){$('#fight-log').textContent='You’re exhausted. Regain your breath.';playerStamina=Math.min(100,playerStamina+7);updateUI();return;}playerStamina-=cost;const d=player.position.distanceTo(enemy.position);const skill=move==='jab'?state.skills[0]:move==='kick'?Math.max(state.skills[1],state.skills[2]):Math.max(state.skills[3],state.skills[4]);const power=clamp(.65+skill/75,.65,1.9);const miss=Math.random()>(.73+skill*.002);if(move==='block'){blockHeld=true;$('#fight-log').textContent='You shell up and read the counter.';setTimeout(()=>blockHeld=false,1200);return;}if(move==='dodge'){dodgeReady=true;$('#fight-log').textContent='You slip off the center line.';setTimeout(()=>dodgeReady=false,950);return;}if(move==='submit'){if(d<3.2&&enemyHP<62&&Math.random()<.25+state.skills[4]*.004){enemyHP=0;$('#fight-log').textContent='You lock it in! No way out!';finishFight('submission');return;}$('#fight-log').textContent='No opening for the submission. Create a scramble first.';enemyAttack();return;}if(move==='grapple'){if(d<3.2&&!miss){const dmg=(7+Math.random()*8)*power;enemyHP=Math.max(0,enemyHP-dmg);$('#fight-log').textContent=`Takedown lands! Top control. ${Math.round(dmg)} damage.`;if(enemyHP<55&&Math.random()<.2){$('#fight-log').textContent='You find the finish in the scramble!';finishFight('submission');return;}}else $('#fight-log').textContent=miss?'The opponent sprawls and stuffs it.':'Close the distance to shoot.';enemyAttack();}else{if(d>3.4){$('#fight-log').textContent='Out of range. Step in and set up your strike.';enemyAttack();return;}if(miss){$('#fight-log').textContent='Whiff. Your opponent slips the shot.';enemyAttack();return;}const dmg=(move==='kick'?10+Math.random()*10:5+Math.random()*7)*power;enemyHP=Math.max(0,enemyHP-dmg);$('#fight-log').textContent=move==='kick'?`Heavy round kick connects for ${Math.round(dmg)} damage!`:`Clean jab lands for ${Math.round(dmg)} damage.`;if(move==='kick')player.rotation.z=.08;if(enemyHP<=0){finishFight(Math.random()<.74?'KO':'TKO');return;}enemyAttack();}updateUI();}
function enemyAttack(){if(!isFighting)return;const miss=Math.random()<.22+state.skills[7]*.003;if(blockHeld){$('#fight-log').textContent='You block the counter. Nice defense.';playerStamina=Math.min(100,playerStamina+2);updateUI();return;}if(dodgeReady||miss){dodgeReady=false;$('#fight-log').textContent='You avoid the counter cleanly.';return;}const defense=state.skills[7]*.11+state.skills[9]*.07;const dmg=Math.max(2,(6+Math.random()*10)-defense);playerHP=Math.max(0,playerHP-dmg);playerStamina=Math.max(0,playerStamina-3);$('#fight-log').textContent=`Counter connects. You take ${Math.round(dmg)} damage.`;updateUI();if(playerHP<=0)finishFight('TKO');}
function finishFight(method){if(!isFighting)return;isFighting=false;clearInterval(fightInterval);$('#fight-hud').classList.remove('active');worldGroup.visible=true;arenaGroup.visible=false;player.position.set(0,0,-12);player.visible=true;playerHP=clamp(playerHP,0,100);const win=method==='KO'||method==='TKO'||method==='submission'||playerHP>enemyHP;const opponent=$('#enemy-name').textContent;const purse=350+state.wins*480;state.energy=clamp(playerStamina,15,100);state.health=clamp(playerHP,25,100);state.fatigue=Math.min(100,state.fatigue+18);timeAdvance(150);let result,paid;if(win){state.wins++;result='WIN';paid=purse+(method==='KO'||method==='submission'?250:0);state.cash+=paid;state.rank=state.wins>=3?Math.max(1,25-state.wins*2):0;if(method==='KO'||method==='TKO')state.ko++;if(method==='submission')state.subs++;addXP(100);if(state.wins>=15&&!state.belt){state.belt=true;state.cash+=100000;toast('WORLD CHAMPION · $100,000 TITLE BONUS!');}else toast(`VICTORY BY ${method.toUpperCase()} · PURSE $${paid.toLocaleString()}`);}else{state.losses++;result='LOSS';paid=100;state.cash+=paid;state.rank=Math.max(0,state.rank+2);addXP(35);toast(`TOUGH LOSS · SHOW MONEY $${paid}`);}state.record.push({result,method:method.toUpperCase(),opponent:opponent.split('“')[0].trim(),date:`DAY ${state.day}`});state.energy=clamp(state.energy-10,15,100);save();$('#fight-button').textContent='STEP INTO THE CAGE';cameraAngle=0;$('#fight-timer').textContent='03:00';setTimeout(()=>{if(!$('#modal-backdrop').classList.contains('open'))openPanel('career');},450);}
$('#fight-exit').onclick=()=>{if(confirm('Withdraw from this bout? It will count as a loss.')){playerHP=30;finishFight('withdraw');}};
function interact(){if(isFighting)return;if(nearLocation){openLocation(nearLocation);return;}if(state.home){sleepAtHome();return;}toast('EXPLORE THE CITY · VISIT A LOCATION TO INTERACT');}

// Keyboard, pointer camera orbit and touch joystick.
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyE')interact();if(e.code==='Digit1')fightMove('jab');if(e.code==='Digit2')fightMove('kick');if(e.code==='Digit3')fightMove('grapple');if(e.code==='Digit4')fightMove('submit');if(e.code==='Space'&&isFighting)fightMove('block');if(e.code==='ShiftLeft'&&isFighting)fightMove('dodge');if(e.code==='Escape'){closeModal();toggleMap(false);}});window.addEventListener('keyup',e=>keys[e.code]=false);
const canvas=$('#world');canvas.addEventListener('pointerdown',e=>{if(e.target!==canvas||isFighting)return;dragging=true;prevPointer={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-prevPointer.x;prevPointer={x:e.clientX,y:e.clientY};cameraAngle+=dx*.005;});canvas.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('wheel',e=>cameraDistance=clamp(cameraDistance+e.deltaY*.008,5,12),{passive:true});
const joy=$('#joystick'),stick=joy.querySelector('.stick');let joyPointer=null;joy.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joy.setPointerCapture(e.pointerId);joyMove(e);});joy.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)joyMove(e);});function joyMove(e){const r=joy.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),d=Math.hypot(dx,dy),max=28,k=Math.min(1,max/d);stick.style.transform=`translate(${dx*k}px,${dy*k}px)`;mobileVector={x:dx*k/max,z:-dy*k/max};}function resetJoy(){joyPointer=null;stick.style.transform='';mobileVector={x:0,z:0};}joy.addEventListener('pointerup',resetJoy);joy.addEventListener('pointercancel',resetJoy);
document.addEventListener('visibilitychange',()=>{if(document.hidden){save();keys={};resetJoy();}});

init3D();updateUI();

